  const secondary = Array.from(heroic.secondaryEffectIds ?? []).map((id) => contentLabel("heroicAbilities", id, settingId)).filter(Boolean);
  const selected = Boolean(heroic.selected || heroic.primaryEffectId || heroic.name);
  const section = document.createElement("section"); section.className = "genesys-character-story-integration genesys-v1752-story-integration"; section.dataset.characterStoryIntegration = "true";
  section.innerHTML = `<div class="genesys-v1752-story-stack"><section class="genesys-fantasy-panel genesys-ornate-panel genesys-v1752-heroic-panel"><div class="genesys-panel-banner"><div><h2>Heroic Ability</h2><p>Character heroic progression</p></div></div>${selected ? `<div class="genesys-v1752-heroic-name"><strong>${esc(heroic.name || heroic.primaryEffectLabel || "Heroic Ability")}</strong><span>${esc(heroic.primaryEffectLabel || contentLabel("heroicAbilities", heroic.primaryEffectId, settingId))}</span></div><div class="genesys-v1752-heroic-stats"><div><span>Power</span><strong>${esc(text(heroic.powerLevel, "base"))}</strong></div><div><span>Activation</span><strong>${esc(text(heroic.activation, "incidental"))}</strong></div><div><span>Story Cost</span><strong>${integer(heroic.storyPointCost)} SP</strong></div><div><span>Uses</span><strong>${integer(heroic.usesThisSession)}</strong></div></div><div class="genesys-v1752-heroic-details"><span><b>Origin:</b> ${esc(origins.join(" / ") || "-")}</span>${secondary.length ? `<span><b>Secondary:</b> ${esc(secondary.join(" / "))}</span>` : ""}</div>` : '<p class="genesys-empty-row">No Heroic Ability selected.</p>'}</section><section class="genesys-fantasy-panel genesys-ornate-panel genesys-v1752-motivation-panel"><div class="genesys-panel-banner"><div><h2>Motivation</h2><p>Strength / Flaw / Desire / Fear</p></div></div><div class="genesys-v1752-motivation-list">${motivationRow("strength", "Strength", motivation.strength)}${motivationRow("flaw", "Flaw", motivation.flaw)}${motivationRow("desire", "Desire", motivation.desire)}${motivationRow("fear", "Fear", motivation.fear)}</div></section></div>`;
