function actionLabel(id) { return String(id ?? "").replaceAll("-", " ").replace(/\b\w/g, (char) => char.toUpperCase()); }
function magicSkillState(actor, id) { return Array.from(actor?.system?.skills ?? []).find((row) => String(row?.id) === String(id)) ?? { id, rank: 0, career: false }; }
function hasRequiredImplement(actor, tags = []) { if (!tags.length) return true; return Array.from(actor?.items?.contents ?? []).some((item) => item?.type === "implement" && item?.system?.equipped && tags.every((tag) => Array.from(item?.system?.tags ?? []).includes(tag))); }
function mountMagicAccess(root, actor) {
  const panel = root.querySelector("[data-genesys-tab-panel='skills'] .genesys-skills-panel") ?? root.querySelector("[data-genesys-tab-panel='skills']"); if (!panel || panel.querySelector("[data-magic-integration]")) return;
  const settingId = actorSettingId(actor); const rules = game?.genesysContent?.getMagicRules?.(settingId) ?? {}; const ids = Array.from(rules.magicSkillIds ?? []); if (!ids.length) return;
  const defs = new Map((game?.genesysContent?.getContent?.("skills", { settingId }) ?? []).map((row) => [row.id, row]));
  const section = document.createElement("section"); section.className = "genesys-magic-integration genesys-fantasy-panel genesys-v1752-magic-access"; section.dataset.magicIntegration = "true";
  section.innerHTML = `<div class="genesys-panel-banner"><div><h2>Magic Access</h2><p>What this character can cast with each magic skill.</p></div></div><div class="genesys-v1752-magic-grid">${ids.map((id) => { const state = magicSkillState(actor, id); const rule = rules?.skillRules?.[id] ?? {}; const implementReady = !rule.requiresImplement || hasRequiredImplement(actor, rule.requiredImplementTags ?? []); const canCast = Boolean(state.career) && integer(state.rank) >= integer(rules.minimumRankToCast, 1) && implementReady; const blockers = []; if (!state.career) blockers.push("Not a Career Skill"); if (integer(state.rank) < integer(rules.minimumRankToCast, 1)) blockers.push(`Rank ${integer(rules.minimumRankToCast, 1)} required`); if (!implementReady) blockers.push("Required implement not equipped"); const actions = Object.entries(rules.actions ?? {}).filter(([, skills]) => Array.isArray(skills) && skills.includes(id)).map(([action]) => actionLabel(action)); return `<article class="genesys-v1752-magic-card ${canCast ? "available" : "locked"}"><header><strong>${esc(defs.get(id)?.label ?? id)}</strong><span>Rank ${integer(state.rank)}</span></header><div class="genesys-v1752-magic-status"><b>${canCast ? "CASTING ACCESS" : "LOCKED"}</b><span>${state.career ? "Career" : "Non-Career"}</span></div><p>${esc(actions.join(" / ") || "No registered actions")}</p>${blockers.length ? `<small>${esc(blockers.join(" / "))}</small>` : ""}</article>`; }).join("")}</div>`;
  const magicGroup = Array.from(panel.querySelectorAll("details.genesys-skill-group")).find((row) => /^magic/i.test(text(row.querySelector(":scope > summary")?.textContent))); if (magicGroup) magicGroup.before(section); else panel.append(section);
}
function mountQuickPool(root) { const pool = root.querySelector(".genesys-quick-pool"); const actions = root.querySelector("[data-genesys-tab-panel='actions']"); if (!pool || !actions || pool.closest("[data-genesys-tab-panel='actions']")) return; pool.classList.add("genesys-actions-quick-pool"); const toolbar = actions.querySelector(".genesys-actions-toolbar"); if (toolbar) toolbar.after(pool); else actions.prepend(pool); }
function mountEquipment(root, actor) {
  const panel = root.querySelector("[data-genesys-tab-panel='equipment'] .genesys-inventory-panel") ?? root.querySelector("[data-genesys-tab-panel='equipment']"); if (!panel) return;
  if (!panel.querySelector("[data-wallet-summary]")) { const currency = actor?.system?.currency ?? {}; const wallet = document.createElement("div"); wallet.className = "genesys-v1752-wallet"; wallet.dataset.walletSummary = "true"; wallet.innerHTML = `<div><i class="fa-solid fa-coins" aria-hidden="true"></i><span>Wallet</span></div><strong>${integer(currency.value)} ${esc(text(currency.label, "Funds"))}</strong>`; const banner = panel.querySelector(".genesys-panel-banner"); if (banner) banner.after(wallet); else panel.prepend(wallet); }
  const createBar = panel.querySelector(".genesys-item-createbar"); if (createBar && !createBar.querySelector("[data-create-implement]")) { const button = document.createElement("button"); button.type = "button"; button.dataset.createImplement = "true"; button.textContent = "+ Magic Implement"; createBar.append(button); }
  if (panel.querySelector("[data-implements-group]")) return;
  const implements = Array.from(actor?.items?.contents ?? []).filter((item) => item?.type === "implement"); const ids = new Set(implements.map((item) => String(item.id))); for (const row of panel.querySelectorAll("details.genesys-item-group .genesys-item-row")) if (ids.has(String(row.dataset.itemId ?? ""))) row.remove();
  const details = document.createElement("details"); details.className = "genesys-item-group genesys-implements-group genesys-v1752-implements"; details.dataset.implementsGroup = "true"; details.open = true;
  details.innerHTML = `<summary>Magic Implements (${implements.length})</summary><div class="genesys-item-table">${implements.length ? implements.map((item) => `<div class="genesys-item-row genesys-simple-item-row" data-item-id="${esc(item.id)}"><button type="button" class="genesys-item-name" data-v1753-edit-implement="${esc(item.id)}">${esc(item.name)}</button><span>Damage +${integer(item.system?.damage)} / Enc ${integer(item.system?.encumbrance)}</span><label class="genesys-v1752-equipped"><input type="checkbox" data-v1753-implement-equipped="${esc(item.id)}" ${item.system?.equipped ? "checked" : ""}/> Equipped</label><span class="genesys-item-actions"><button type="button" data-v1753-delete-implement="${esc(item.id)}">x</button></span></div>`).join("") : '<p class="genesys-empty-row">No magic implements yet.</p>'}</div>`;
  const attachments = Array.from(panel.querySelectorAll("details.genesys-item-group")).find((row) => /^attachments/i.test(text(row.querySelector(":scope > summary")?.textContent))); if (attachments) attachments.before(details); else panel.append(details);
}
async function updateMotivation(actor, facet, value) { const current = actor?.system?.motivations?.toObject?.() ?? actor?.system?.motivations ?? {}; const next = { ...current, [facet]: value }; const summary = game?.genesysHeroic?.motivations?.summarize?.(next) ?? ""; await actor.update({ [`system.motivations.${facet}`]: value, "system.profile.motivation": summary }); }
function bindRoot(root, actor) {
  if (root.dataset.genesysV1753Events === "true") return; root.dataset.genesysV1753Events = "true";
  root.addEventListener("change", async (event) => { const motivation = event.target?.closest?.("[data-v1753-motivation]"); if (motivation) { try { await updateMotivation(actor, motivation.dataset.v1753Motivation, motivation.value); } catch (error) { console.error(`${SYSTEM_ID} | Motivation update failed`, error); ui?.notifications?.error?.(String(error?.message ?? error)); } return; } const equipped = event.target?.closest?.("[data-v1753-implement-equipped]"); if (equipped) { const item = actor.items?.get?.(String(equipped.dataset.v1753ImplementEquipped ?? "")); if (item) await item.update({ "system.equipped": Boolean(equipped.checked) }); } });
  root.addEventListener("click", async (event) => { const create = event.target?.closest?.("[data-create-implement]"); const edit = event.target?.closest?.("[data-v1753-edit-implement]"); const remove = event.target?.closest?.("[data-v1753-delete-implement]"); if (!create && !edit && !remove) return; event.preventDefault(); event.stopImmediatePropagation(); if (create) { const created = await actor.createEmbeddedDocuments("Item", [{ name: "New Magic Implement", type: "implement", system: { damage: 0, encumbrance: 0, priceMode: "priced", materialId: "", tags: [], equipped: false, notes: "" } }]); created?.[0]?.sheet?.render?.({ force: true }); return; } const id = String(edit?.dataset.v1753EditImplement ?? remove?.dataset.v1753DeleteImplement ?? ""); const item = actor.items?.get?.(id); if (!item) return; if (edit) item.sheet?.render?.({ force: true }); if (remove) await item.delete(); }, true);
}
function mountRoot(root) { const actor = actorForRoot(root); if (!actor) return; mountBiography(root, actor); mountMagicAccess(root, actor); mountQuickPool(root); mountEquipment(root, actor); bindRoot(root, actor); }
function scan() { scanQueued = false; for (const root of document.querySelectorAll("[data-genesys-sheet-tabs]")) mountRoot(root); }
function queueScan() { if (scanQueued) return; scanQueued = true; requestAnimationFrame(scan); }
function boot() { scan(); if (!observer) { observer = new MutationObserver(queueScan); observer.observe(document.body, { childList: true, subtree: true }); } for (const delay of [50, 150, 350, 750, 1500]) setTimeout(scan, delay); console.log(`${SYSTEM_ID} | 0.0.1753 Character Sheet integration ready`); }
console.log(`${SYSTEM_ID} | 0.0.1753 Character Sheet integration module loaded`);
if (globalThis.game?.ready) boot(); else globalThis.Hooks?.once?.("ready", boot);
